def solve(expr):
  if expr.isdigit():
    return int(expr)

  ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b, '/': lambda a, b: a // b}

  expr = expr.replace(' ', '')

  if '(' in expr:
    start = expr.find('(')
    end = expr.find(')')

    while start != -1 and end != -1:
      subexpression = expr[start + 1:end]
      expr = expr[:start] + str(solve(subexpression)) + expr[end + 1:]
      start = expr.find('(')
      end = expr.find(')')

  tokens = expr.split()
  stack = []

  for token in tokens:
    if token in ops:
      operand2 = stack.pop()
      operand1 = stack.pop()
      result = ops[token](operand1, operand2)
      stack.append(result)
    else:
      stack.append(int(token))

  return stack[0]
