def solve(expr):
    def eval_expr(expr):
        if expr.isdigit():
            return int(expr)
        if '(' in expr and ')' in expr:
            start = expr.find('(')
            end = expr.rfind(')')
            return eval_expr(expr[start + 1:end])
        operators = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b, '/': lambda a, b: a // b}
        for op in operators:
            if op in expr:
                parts = expr.split(op)
                left = eval_expr(parts[0])
                right = eval_expr(parts[1])
                return operators[op](left, right)
    return eval_expr(expr)
