def solve(expr):
    expr = expr.replace(' ', '')
    if not expr:
        return 0
    tokens = []
    current_num = ''
    for char in expr:
        if char.isdigit():
            current_num += char
        elif char in '+-*/()':
            if current_num:
                tokens.append(int(current_num))
                current_num = ''
            tokens.append(char)
    if current_num:
        tokens.append(int(current_num))

    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a // b,
    }

    for token in tokens:
        if isinstance(token, int):
            stack.append(token)
        elif token in operators:
            operand2 = stack.pop()
            operand1 = stack.pop()
            result = operators[token](operand1, operand2)
            stack.append(result)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                operand2 = stack.pop()
                operand1 = stack.pop()
                operator = stack.pop()
                result = operators[operator](operand1, operand2)
                stack.append(result)
            stack.pop()  # Remove the '('

    return stack[0] 
